// packages/omo-opencode/src/cli/config-migrate.ts
init_startup_migration();
import { posix as posix11 } from "node:path";
function reports(result) {
  return result.results.map((entry) => ({
    diagnostics: entry.diagnostics,
    movePlan: entry.preview?.backupMoves ?? [],
    status: entry.status,
    ...entry.preview === undefined ? {} : { targetPath: entry.preview.targetPath, transform: entry.preview.transform }
  }));
}
function printText(report, output) {
  for (const entry of report) {
    output(`status: ${entry.status}`);
    if (entry.targetPath !== undefined)
      output(`target: ${entry.targetPath}`);
    if (entry.transform !== undefined)
      output(`transform: ${JSON.stringify(entry.transform, null, 2)}`);
    if (entry.movePlan.length > 0)
      output(`move-plan: ${JSON.stringify(entry.movePlan, null, 2)}`);
    for (const diagnostic of entry.diagnostics)
      output(`conflict: ${diagnostic}`);
  }
}
function runConfigMigrate(options = {}) {
  const environment2 = options.environment ?? process.env;
  const homeDir = environment2["HOME"] ?? environment2["USERPROFILE"];
  const output = options.output ?? console.log;
  const result = runOpenCodeStartupMigration({
    cwd: options.cwd ?? process.cwd(),
    dryRun: options.dryRun ?? false,
    environment: environment2,
    ...homeDir === undefined ? {} : { env: { HOME: homeDir }, homeDir },
    pathOperations: posix11
  });
  const report = reports(result);
  const response = {
    dryRun: options.dryRun ?? false,
    error: result.error,
    journalResumed: result.journalResumed,
    migratedFrom: result.migratedFrom,
    migrations: report,
    skippedConflictCount: result.skippedConflictCount
  };
  if (options.json) {
    output(JSON.stringify(response, null, 2));
  } else if (result.error !== undefined) {
    output(`Configuration migration failed: ${result.error}`);
  } else {
    if (result.journalResumed)
      output("Recovered pending migration journal.");
    printText(report, output);
    if (report.every((entry) => entry.status === "skipped"))
      output("Nothing to migrate.");
  }
  return result.error === undefined ? 0 : 1;
}

